digraph JKFF {
    node [shape=box, style="filled", fillcolor="#f9f9f9"];
    Clock [shape=circle, label="Clock (CLK)"];
    J [shape=circle, label="J"];
    K [shape=circle, label="K"];
    Set [shape=box, label="S"];
    Reset [shape=box, label="R"];
    Hold [shape=box, label="Q_current"];
    Q_next [shape=box, label="Q_next"];

    J -> AND_1;
    NOT_Q [shape=circle, label="NOT Q_current"];
    NOT_Q -> OR_1;

    AND_1 [shape=diamond, label="J AND NOT Q"];
    AND_1 -> OR_1;

    K -> AND_2;
    Q_current -> AND_2;

    AND_2 [shape=diamond, label="NOT K AND Q_current"];
    AND_2 -> OR_1;

    OR_1 [shape=hexagon, label="OR Gate"];
    OR_1 -> Q_next;

    // Connecting the clock to the output via a D-type register/latch is complex, 
    // so we show the input logic that determines the next state Q_next.
}

