flowchart TD
    A[Start] --> B{Current State Q and Inputs JK};
    B --> C{JK=00?};
    C -- Yes --> D[Q_next = Q (No change)];
    C -- No --> E{JK=01?};
    E -- Yes --> F[Q_next = 1 (Set)];
    E -- No --> G{JK=10?};
    G -- Yes --> H[Q_next = 0 (Reset)];
    G -- No --> I[Q_next = NOT Q (Toggle)];
    D --> J[Update Q = Q_next];
    F --> J;
    H --> J;
    I --> J;
    J --> K[End];

